from qiskit import QuantumCircuit

def build_constraint_1(qc, problem_qubits, flag, scratch):
    """
    edge (0,1): vertices 0 and 1 must have different colors
    Vertices: 0 -> bits [0,1]; 1 -> bits [2,3]
    """
    scratch_q = scratch[0]
    # extract qubits for both vertices
    a0, a1 = problem_qubits[0], problem_qubits[1]
    b0, b1 = problem_qubits[2], problem_qubits[3]
    qubits = [a0, a1, b0, b1]

    # all patterns (a0,a1,b0,b1) where colors are equal
    equal_patterns = [
        [0, 0, 0, 0],   # both 00
        [0, 0, 1, 1],   # 00 and 11
        [1, 1, 0, 0],   # 11 and 00
        [1, 1, 1, 1],   # both 11
        [0, 1, 0, 1],   # both 01 (color 1)
        [1, 0, 1, 0],   # both 10 (color 2)
    ]

    # compute: set scratch = 1 iff input matches one of the patterns (colors equal)
    for pattern in equal_patterns:
        for i, bit in enumerate(pattern):
            if bit == 0:
                qc.x(qubits[i])
        qc.mcx(qubits, scratch_q, ancilla_qubits=[], mode='noancilla')
        for i, bit in enumerate(pattern):
            if bit == 0:
                qc.x(qubits[i])

    # now flip flag iff scratch == 0 (i.e., colors differ)
    qc.x(scratch_q)
    qc.cx(scratch_q, flag)
    qc.x(scratch_q)

    # uncompute scratch to |0>
    for pattern in equal_patterns:
        for i, bit in enumerate(pattern):
            if bit == 0:
                qc.x(qubits[i])
        qc.mcx(qubits, scratch_q, ancilla_qubits=[], mode='noancilla')
        for i, bit in enumerate(pattern):
            if bit == 0:
                qc.x(qubits[i])


