def canonicalize(qc, q0, q1, anc):
    """If (q0,q1) == (1,1), flip both to (0,0) (self-inverse)."""
    qc.ccx(q0, q1, anc)
    qc.cx(anc, q0)
    qc.cx(anc, q1)
    qc.ccx(q0, q1, anc)

def check_given1(qc, q0, q1, s):
    """s ^= ( (not q0) and q1 )"""
    qc.x(q0)
    qc.ccx(q0, q1, s)
    qc.x(q0)

def check_given2(qc, q0, q1, s):
    """s ^= ( q0 and (not q1) )"""
    qc.x(q1)
    qc.ccx(q0, q1, s)
    qc.x(q1)

def check_given0(qc, q0, q1, s):
    """s ^= (q0 == q1)"""
    qc.cx(q0, s)
    qc.cx(q1, s)
    qc.x(s)

def flip_if_not(qc, s, flag):
    """Flip flag iff s == 0."""
    qc.x(s)
    qc.cx(s, flag)
    qc.x(s)

