    # cells (0,0) and (0,1) must be different
    a0, a1 = problem_qubits[0], problem_qubits[1]
    b0, b1 = problem_qubits[2], problem_qubits[3]
    anc1, anc2, anc3, anc4 = problem_qubits[4], problem_qubits[5], problem_qubits[6], problem_qubits[7]
    s = scratch[0]

    canonicalize(qc, a0, a1, anc1)
    canonicalize(qc, b0, b1, anc2)

    qc.cx(a0, anc3); qc.cx(b0, anc3); qc.x(anc3)
    qc.cx(a1, anc4); qc.cx(b1, anc4); qc.x(anc4)

    qc.ccx(anc3, anc4, s)
    flip_if_not(qc, s, flag)

    qc.ccx(anc3, anc4, s)
    qc.x(anc4); qc.cx(b1, anc4); qc.cx(a1, anc4)
    qc.x(anc3); qc.cx(b0, anc3); qc.cx(a0, anc3)
    canonicalize(qc, b0, b1, anc2)
    canonicalize(qc, a0, a1, anc1)

