def build_constraint_1(qc, problem_qubits, flag, scratch):
    a0, a1 = problem_qubits[0], problem_qubits[1]
    b0, b1 = problem_qubits[2], problem_qubits[3]
    s = scratch[0]

    # pre-flip flag to prepare for inequality detection
    qc.x(flag)

    # Helper to apply a pattern: list of qubits to invert before mct and after
    def apply_pattern(invert_a0, invert_a1, invert_b0, invert_b1):
        # invert qubits that should be 0 in the pattern
        if invert_a0: qc.x(a0)
        if invert_a1: qc.x(a1)
        if invert_b0: qc.x(b0)
        if invert_b1: qc.x(b1)
        # multi-controlled Toffoli
        qc.mct([a0, a1, b0, b1], s, None, mode='basic')
        # undo inversions to restore original qubits
        if invert_a0: qc.x(a0)
        if invert_a1: qc.x(a1)
        if invert_b0: qc.x(b0)
        if invert_b1: qc.x(b1)
        # flip flag if pattern matched
        qc.cx(s, flag)
        # uncompute scratch
        if invert_a0: qc.x(a0)
        if invert_a1: qc.x(a1)
        if invert_b0: qc.x(b0)
        if invert_b1: qc.x(b1)
        qc.mct([a0, a1, b0, b1], s, None, mode='basic')
        if invert_a0: qc.x(a0)
        if invert_a1: qc.x(a1)
        if invert_b0: qc.x(b0)
        if invert_b1: qc.x(b1)

    # Pattern: (0,0,0,0) -> invert all
    apply_pattern(True, True, True, True)
    # Pattern: (0,0,1,1) -> invert a0,a1 only
    apply_pattern(True, True, False, False)
    # Pattern: (1,1,0,0) -> invert b0,b1 only
    apply_pattern(False, False, True, True)
    # Pattern: (1,1,1,1) -> no inversion
    apply_pattern(False, False, False, False)
    # Pattern for value 1: (1,0,1,0) -> invert a1,b1
    apply_pattern(False, True, False, True)
    # Pattern for value 2: (0,1,0,1) -> invert a0,b0
    apply_pattern(True, False, True, False)


